"""KRD benchmark opponent (generated by opponents/build_opponents.py -- edit _base_agent.py).

Standalone: only poker_agent_sdk + stdlib. Stateless (returns b"" memory); every decision is
derived from `state` alone. Randomness is deterministic per (table, hand, seat, decision) via
crc32, so fixed-seed benchmarks are reproducible.
"""
import math
import os
import zlib

from poker_agent_sdk import Action, Agent as BaseAgent

STYLE = {'reveal': 'high', 'naive_reveals': True, 'reader': False, 'maniac': False, 'pf_bb': 15, 'pf_jam': {'early': 9, 'mid': 8, 'late': 6, 'sb': 5, 'bb': 8}, 'pf_short_bonus': 1.5, 'pf_call': 9, 'open': {'early': 9, 'mid': 8, 'late': 6, 'sb': 7, 'bb': 10}, 'open_size': 2.5, 'threebet': 10, 'flat': 8, 'flat_frac': 0.08, 'fourbet': 12, 'value_cat': 2, 'aggr': 1.0, 'bubble_players': 0, 'bubble_tighten': 0, 'name': 'reveal_high'}

_DEBUG = bool(os.environ.get("KRD_OPP_DEBUG"))  # re-raise instead of check/fold
RV = {r: i + 2 for i, r in enumerate("23456789TJQKA")}
_CHEN_HI = {14: 10.0, 13: 8.0, 12: 7.0, 11: 6.0}


def chen(a, b):
    """Chen formula on two card strings. Range about -1..20 (AA=20, KK=16, AKs=12, 72o=-1)."""
    r1, r2 = RV[a[0]], RV[b[0]]
    if r1 < r2:
        r1, r2 = r2, r1
    pts = _CHEN_HI.get(r1, r1 / 2.0)
    if r1 == r2:
        return max(2 * pts, 5.0)
    if a[1] == b[1]:
        pts += 2
    gap = r1 - r2 - 1
    pts -= (0, 1, 2, 4)[gap] if gap < 4 else 5
    if gap <= 1 and r1 < 12:
        pts += 1
    return float(math.ceil(pts))


def tiebreak(a, b):
    r1, r2 = RV[a[0]], RV[b[0]]
    return chen(a, b) * 100 + max(r1, r2) * 15 + min(r1, r2)


def rnd(state, salt=0):
    key = f"{state.config.table_id}|{state.hand_number}|{state.seat}|{len(state.history)}|{salt}"
    return zlib.crc32(key.encode()) / 4294967296.0


# ---------------------------------------------------------------- actions
def raise_to(state, total):
    r = state.can("raise")
    if not r:
        return call_or_check(state)
    return Action.raise_to(max(r.min_amount, min(r.max_amount, int(total))))


def jam(state):
    r = state.can("raise")
    if r:
        return Action.raise_to(r.max_amount)
    return call_or_check(state)


def call_or_check(state):
    if state.can("check"):
        return Action.check()
    if state.can("call"):
        return Action.call()
    return Action.fold()


def check_or_fold(state):
    if state.can("check"):
        return Action.check()
    if state.can("fold"):
        return Action.fold()
    first = state.legal_actions[0]
    return Action(first.kind, first.min_amount)


# ---------------------------------------------------------------- hand reading
def preflop_info(state):
    """(raises, last_raiser, limpers, acted_seats) from this hand's preflop events."""
    raises, raiser, limpers, acted = 0, None, 0, set()
    for e in state.history:
        if e.kind == "board":
            break
        if e.kind == "raise":
            raises += 1
            raiser = e.seat
            acted.add(e.seat)
        elif e.kind == "call":
            if raises == 0:
                limpers += 1
            acted.add(e.seat)
        elif e.kind in ("fold", "check"):
            acted.add(e.seat)
    return raises, raiser, limpers, acted


def preflop_aggressor(state):
    raiser = None
    for e in state.history:
        if e.kind == "board":
            break
        if e.kind == "raise":
            raiser = e.seat
    return raiser


def street_aggressor(state):
    """Seat of the last bettor/raiser on the current street (None if none)."""
    seat = None
    for e in state.history:
        if e.kind == "board":
            seat = None
        elif e.kind == "raise":
            seat = e.seat
    return seat


def position(state):
    """(pos, n): pos counted from the button among non-busted seats (0=BTN, 1=SB, 2=BB...).
    Heads-up: 0 = BTN/SB, 1 = BB."""
    alive = [s.seat for s in state.seats if s.status != "busted"]
    n = len(alive)
    if state.button in alive:
        k = alive.index(state.button)
        order = alive[k:] + alive[:k]
    else:
        order = alive
    pos = order.index(state.seat) if state.seat in order else 0
    return pos, n


def pos_class(pos, n):
    """early / mid / late / sb / bb."""
    if n == 2:
        return "late" if pos == 0 else "bb"
    if pos == 0:
        return "late"
    if pos == 1:
        return "sb"
    if pos == 2:
        return "bb"
    if pos == n - 1:
        return "late"  # cutoff
    if n - pos <= 3:
        return "mid"
    return "early"


def revealed_rank(state, seat):
    if seat is None:
        return None
    c = (state.variant or {}).get("revealed", {}).get(seat)
    return RV[c[0]] if c else None


def hand_cat(cards, board):
    """(cat, draw). cat: 0 nothing, 1 weak pair, 2 top pair/overpair, 3 two pair/trips,
    4 straight/flush/full house+. draw: flush draw or open-ended straight draw."""
    mine = [RV[c[0]] for c in cards]
    br = [RV[c[0]] for c in board]
    allc = list(cards) + list(board)
    allr = mine + br
    cnt = {}
    for r in allr:
        cnt[r] = cnt.get(r, 0) + 1
    suits = {}
    for c in allc:
        suits[c[1]] = suits.get(c[1], 0) + 1
    my_suits = {c[1] for c in cards}
    flush = any(v >= 5 and s in my_suits for s, v in suits.items())
    fdraw = len(board) < 5 and any(v == 4 and s in my_suits for s, v in suits.items())
    rs = set(allr)
    if 14 in rs:
        rs.add(1)
    straight, oesd = False, False
    myset = set(mine) | ({1} if 14 in mine else set())
    for lo in range(1, 11):
        win = set(range(lo, lo + 5))
        if win <= rs and win & myset:
            straight = True
    for lo in range(2, 11):
        win = set(range(lo, lo + 4))
        if win <= rs and win & myset and lo + 4 <= 14 and lo - 1 >= 1:
            oesd = True
    oesd = oesd and len(board) < 5
    trips_mine = any(cnt[r] >= 3 for r in set(mine))
    pairs_mine = [r for r in set(mine) if cnt[r] >= 2]
    board_pairs = [r for r in set(br) if cnt[r] >= 2 and r not in mine]
    quads = any(cnt[r] >= 4 for r in set(mine))
    if quads or (trips_mine and (len(pairs_mine) >= 2 or board_pairs)):
        return 4, False
    if flush or straight:
        return 4, False
    if trips_mine or len(pairs_mine) >= 2:
        return 3, False
    draw = fdraw or oesd
    if pairs_mine:
        r = max(pairs_mine)
        top = max(br) if br else 0
        if r >= top:
            return 2, draw
        return 1, draw
    return 0, draw


# ---------------------------------------------------------------- the agent
class Agent(BaseAgent):
    def act(self, state, memory):
        try:
            if state.phase == "choose":
                action = self.choose(state)
            elif state.phase != "betting":
                first = state.legal_actions[0]
                action = Action(first.kind, first.min_amount)
            elif not state.board:
                action = self.preflop(state)
            else:
                action = self.postflop(state)
        except Exception:
            if _DEBUG:
                raise
            action = check_or_fold(state)
        return action, b""

    # ---------------- choose
    def choose(self, state):
        c = state.cards
        pairs = [(a, b) for a in range(3) for b in range(3) if a < b]
        a, b = max(pairs, key=lambda p: tiebreak(c[p[0]], c[p[1]]))
        hi, lo = (a, b) if RV[c[a][0]] >= RV[c[b][0]] else (b, a)
        mode = STYLE["reveal"]
        if mode == "high":
            return Action.choose(keep=lo, reveal=hi)
        if mode == "random":
            if rnd(state, 7) < 0.5:
                return Action.choose(keep=lo, reveal=hi)
        return Action.choose(keep=hi, reveal=lo)

    # ---------------- preflop
    def preflop(self, state):
        S = STYLE
        bb = max(state.blinds[1], 1)
        me = next(s for s in state.seats if s.seat == state.seat)
        stack_total = me.stack + me.bet
        # effective stack vs the biggest other live stack
        others = [s.stack + s.bet for s in state.seats
                  if s.seat != state.seat and s.status in ("active", "all_in")]
        eff = min(stack_total, max(others) if others else stack_total)
        eff_bb = eff / bb
        ch = chen(*state.cards)
        raises, raiser, limpers, acted = preflop_info(state)
        pos, n = position(state)
        pc = pos_class(pos, n)
        to_call = state.to_call
        cur = me.bet + to_call
        u = rnd(state, 1)
        late_game = state.players_remaining <= S.get("bubble_players", 0)

        # reveal reading: rank of the aggressor's shown card; ranks shown by players behind
        rr = revealed_rank(state, raiser)
        behind = [s.seat for s in state.seats
                  if s.status == "active" and s.seat != state.seat and s.seat not in acted]
        behind_ranks = [revealed_rank(state, x) for x in behind]
        behind_ranks = [r for r in behind_ranks if r is not None]

        adj_open, adj_call = 0.0, 0.0
        if S.get("reader"):
            if behind_ranks and max(behind_ranks) <= 9:
                adj_open -= 2.5  # everybody left looks weak: attack
            elif any(r >= 12 for r in behind_ranks):
                adj_open += 1.5
            if rr is not None:
                if rr >= 12:
                    adj_call += 4  # shown A/K/Q under "reveal low" => strong hand: get out
                elif rr <= 9:
                    adj_call -= 2.5
        elif S.get("naive_reveals"):
            if rr is not None:
                adj_call += 1 if rr >= 13 else (-1 if rr <= 8 else 0)
            if any(r == 14 for r in behind_ranks):
                adj_open += 0.5
        if late_game:
            adj_open += S.get("bubble_tighten", 0)
            adj_call += S.get("bubble_tighten", 0)

        if S.get("maniac"):
            return self._maniac_pre(state, ch, raises, cur, bb, u, stack_total)

        # ---- push / fold
        if eff_bb <= S["pf_bb"]:
            if raises == 0:
                if pc == "bb" and to_call == 0:
                    if ch >= S["pf_jam"]["bb"] + adj_open:
                        return jam(state)
                    return call_or_check(state)
                thr = S["pf_jam"][pc] + adj_open - (S["pf_short_bonus"] if eff_bb <= 8 else 0)
                if ch >= thr:
                    return jam(state)
                return check_or_fold(state)
            # facing a raise / jam
            if S.get("call_any_pair_ace"):
                r1, r2 = RV[state.cards[0][0]], RV[state.cards[1][0]]
                if r1 == r2 or 14 in (r1, r2) or ch >= S["pf_call"] + adj_call:
                    return jam(state)
                return check_or_fold(state)
            thr = S["pf_call"] + adj_call
            if to_call <= 0.3 * stack_total or eff_bb <= 6:
                thr -= 1.5
            if ch >= thr:
                return jam(state)
            return check_or_fold(state)

        # ---- deep stacked
        if raises == 0:
            if to_call == 0:  # BB option
                if ch >= S["open"]["bb"] + adj_open:
                    return raise_to(state, cur + int(3 * bb) + limpers * bb)
                return Action.check()
            thr = S["open"][pc] + adj_open + 0.5 * limpers
            if ch >= thr:
                return raise_to(state, int(S["open_size"] * bb) + limpers * bb)
            if pc == "sb" and limpers and ch >= thr - 2:
                return call_or_check(state)
            return check_or_fold(state)
        if raises == 1:
            if ch >= S["threebet"] + adj_call:
                return raise_to(state, 3 * cur)
            if ch >= S["flat"] + adj_call and to_call <= S["flat_frac"] * stack_total:
                return call_or_check(state)
            if ch >= S["threebet"] + adj_call - 1 and to_call >= 0.4 * stack_total:
                return jam(state)
            return check_or_fold(state)
        # 4-bet+
        if ch >= S["fourbet"] + adj_call:
            return jam(state)
        if ch >= S["fourbet"] + adj_call - 1.5 and to_call <= 0.12 * stack_total:
            return call_or_check(state)
        return check_or_fold(state)

    def _maniac_pre(self, state, ch, raises, cur, bb, u, stack_total):
        if raises == 0:
            if ch >= 9 or (ch >= 3 and u < 0.35):
                return jam(state)
            if ch >= 2 or u < 0.5:
                return raise_to(state, 4 * bb)
            return call_or_check(state) if state.to_call <= bb else check_or_fold(state)
        if ch >= 8 or u < 0.3:
            return jam(state)
        if ch >= 5 and state.to_call <= 0.25 * stack_total:
            return call_or_check(state)
        return check_or_fold(state)

    # ---------------- postflop
    def postflop(self, state):
        S = STYLE
        me = next(s for s in state.seats if s.seat == state.seat)
        stack = me.stack
        pot = state.pot
        to_call = state.to_call
        cat, draw = hand_cat(state.cards, state.board)
        live = [s for s in state.seats if s.status in ("active", "all_in") and s.seat != state.seat]
        n_live = len(live)
        u = rnd(state, 2)
        aggr = S["aggr"]
        river = len(state.board) == 5

        # naive reveal use: a live opponent whose shown card pairs a board rank above my pair
        live_ranks = [revealed_rank(state, s.seat) for s in live]
        live_ranks = [r for r in live_ranks if r is not None]
        br = [RV[c[0]] for c in state.board]
        if cat == 2 and (S.get("naive_reveals") or S.get("reader")):
            mine_hi = max(RV[c[0]] for c in state.cards)
            if any(r in br and r > mine_hi for r in live_ranks):
                cat = 1

        bettor = street_aggressor(state)
        brank = revealed_rank(state, bettor)

        def bet(frac):
            return raise_to(state, me.bet + to_call + int(frac * (pot + to_call)))

        spr = stack / max(pot, 1)
        if to_call == 0:
            if cat >= 3:
                return bet(0.75)
            if cat == 2 and S["value_cat"] <= 2:
                return bet(0.6) if spr > 0.8 else jam(state)
            if S.get("reader") and live_ranks and max(live_ranks) <= 9 and n_live <= 2:
                return bet(0.6)  # everybody left showed low: they hold "nothing high"
            if draw and u < 0.5 * aggr and not river:
                return bet(0.5)
            pfa = preflop_aggressor(state) == state.seat
            if pfa and len(state.board) == 3 and n_live <= 2 and u < 0.7 * aggr:
                return bet(0.5)
            if S.get("maniac") and u < 0.6:
                return bet(0.7)
            return Action.check()

        odds = to_call / (pot + to_call)
        commit = to_call >= 0.5 * stack
        strong_bettor = S.get("reader") and brank is not None and brank >= 12
        weak_bettor = S.get("reader") and brank is not None and brank <= 9
        if cat >= 4:
            return raise_to(state, me.bet + 3 * to_call + pot) if spr > 1 else jam(state)
        if cat == 3:
            if strong_bettor and odds > 0.3 and not S.get("maniac"):
                return call_or_check(state)
            if u < 0.5 * aggr or spr < 1.5:
                return raise_to(state, me.bet + 3 * to_call + pot // 2)
            return call_or_check(state)
        if cat == 2:
            if strong_bettor:
                return call_or_check(state) if odds <= 0.2 else check_or_fold(state)
            if S["value_cat"] > 2 and odds > 0.25:
                return check_or_fold(state)
            if odds <= 0.4 or (commit and spr < 1.2):
                return call_or_check(state)
            return check_or_fold(state)
        if cat == 1:
            lim = 0.3 if weak_bettor else 0.25
            if S.get("maniac"):
                lim = 0.4
            if strong_bettor:
                lim = 0.12
            if odds <= lim * (1 if S["value_cat"] <= 2 else 0.6):
                return call_or_check(state)
            return check_or_fold(state)
        if draw and not river and odds <= (0.3 if not strong_bettor else 0.2):
            return call_or_check(state)
        if weak_bettor and odds <= 0.2 and not river:
            return call_or_check(state)
        if S.get("maniac") and u < 0.15:
            return jam(state)
        return check_or_fold(state)
